let state=null,profile,clockTimer,guestPollTimer,stateRevision=0,pollFailures=0,buildTool='wall',monsterChoice='',landingMode='',howOpen=globalThis.localStorage?.getItem('trapboundHowSeen')!=='1'&&globalThis.sessionStorage?.getItem('trapboundTutorialSeen')!=='1',realmFlashUntil=0,audioCtx=null,heartbeatTimer=0,portalHumTimer=0,recentDiscoveries=new Map(),lastStepSound=0;
