const CHARACTERS={fox:{name:'Leafstep Scout',class:'Ranger',icon:'🏹',sprite:0,buff:'Start with 120 HP (others have 100).',story:'A fearless mapmaker trying to chart every impossible corridor before the dungeon erases itself.'},witch:{name:'Moonveil Mage',class:'Mage',icon:'🌙',sprite:1,buff:'+1 tile range for ranged weapons; melee range stays 1.',story:'She cracked the old moon seal and now competes to learn which team can control its strange magic.'},golem:{name:'Mossback Guardian',class:'Guardian',icon:'🛡️',sprite:2,buff:'Block the first monster hit each floor.',story:'The last gardener of the Moonstone Vault, awakened to keep the Jam dangerous—but never unfair.'},wisp:{name:'Rook Shadowblade',class:'Duelist',icon:'⚔️',sprite:3,buff:'Stun effects last half as long.',story:'A former maze architect who knows every trick except the ones another player invents.'},goblin:{name:'Sunseed Forager',class:'Forager',icon:'🍄',sprite:4,buff:'+20 points per treasure.',story:'A cheerful relic hunter earning enough treasure to rebuild the village outside the shifting maze.'},tinker:{name:'Gearleaf Trapper',class:'Trapper',icon:'🪤',sprite:5,buff:'Disarm the first trap each floor.',story:'The arena’s original mechanic. Half the traps are repairs; the other half are competitive inspiration.'}}; try{profile=JSON.parse(sessionStorage.getItem('dungeonJamProfile')||'null')}catch{}
const AVATAR_MODELS={scout:{name:'Scout',icon:'🧝'},mage:{name:'Mage',icon:'🧙'},knight:{name:'Knight',icon:'🧑‍🚀'},rogue:{name:'Rogue',icon:'🥷'},healer:{name:'Healer',icon:'🧑‍⚕️'},robot:{name:'Robot',icon:'🤖'}};
