let stickPointer=null,stickOrigin=null,stickDirection=null,stickLast=0;
document.addEventListener('pointerdown',e=>{const stick=e.target.closest('[data-joystick]');if(!stick||state?.phase!=='run')return;const b=stick.getBoundingClientRect();stickPointer=e.pointerId;stickOrigin={x:b.left+b.width/2,y:b.top+b.height/2};document.body.setPointerCapture?.(e.pointerId);updateStick(e);e.preventDefault()});
function updateStick(e){if(e.pointerId!==stickPointer||!stickOrigin)return;const x=e.clientX-stickOrigin.x,y=e.clientY-stickOrigin.y;stickDirection=Math.hypot(x,y)<10?null:Math.abs(x)>Math.abs(y)?[Math.sign(x),0]:[0,Math.sign(y)];const knob=document.querySelector('[data-joystick] i');if(knob)knob.style.transform=`translate(${Math.max(-25,Math.min(25,x))}px,${Math.max(-25,Math.min(25,y))}px)`;if(stickDirection&&Date.now()-stickLast>180){stickLast=Date.now();send({type:'move',dir:stickDirection})}}
document.addEventListener('pointermove',updateStick);function releaseStick(){stickPointer=null;stickOrigin=null;stickDirection=null;const knob=document.querySelector('[data-joystick] i');if(knob)knob.style.transform=''}
document.addEventListener('pointerup',releaseStick);document.addEventListener('pointercancel',releaseStick);window.addEventListener('blur',releaseStick);window.addEventListener('orientationchange',releaseStick);
setInterval(()=>{if(stickDirection&&state?.phase==='run'&&Date.now()-stickLast>((state.players.find(p=>p.id===state.me)?.speedUntil||0)>Date.now()?120:210)){stickLast=Date.now();send({type:'move',dir:stickDirection})}const me=state?.players.find(p=>p.id===state.me),count=document.querySelector('[data-respawn-count]');if(count&&me?.respawnAt)count.textContent='RESPAWNING IN '+Math.max(0,Math.ceil((me.respawnAt-Date.now())/1000))+'...';const realmCount=document.querySelector('[data-realm-count]');if(realmCount&&state?.pvpArena)realmCount.textContent=Math.max(0,Math.ceil((state.pvpArena.until-Date.now())/1000))+'s';const ability=document.querySelector('[data-ability]');if(ability&&me){let left=Math.max(0,Math.ceil(((me.lastAbility||0)+12000-Date.now())/1000));ability.disabled=me.eliminated||me.escaped||left>0;ability.querySelector('span').textContent=left?'Ready in '+left+'s':abilityName(me.character)+' · Q'}},100);
